subsection.content:
Exemple de déclaration de quelques variables :

VARIABLE Age, Som, Nombre : Entier ;

Prix, Moyenne : Réel ;

Chiffre : Caractère ;

Chaine : Chaîne de caractères ;

Gagner : Booléen ;

Exemples :

Nombre <- 5 ;

Som <- Nombre ;

Moyenne <- (note1 + note2)/2 ;

ALGORITHME Trace ;

VAR X, Y, Z : Entier ;

DÉBUT

  X <- 3 ;

  Y <- 7 ;

  Z <- X ;

  X <- Y ;

  Z <- Z + 1 ;

  ÉCRIRE(2, X, Y) ;

  ÉCRIRE(X + 1 / 2) ;

FIN.
